use super::{ExecutionError,ExecutionRequest,Executor,Quote}; use crate::domain::trade::Fill; use async_trait::async_trait; use chrono::Utc; use rust_decimal::Decimal;
pub struct PaperExecutor<E>{ quotes:E, fill_haircut_bps:u32 }
impl<E> PaperExecutor<E>{pub fn new(quotes:E,fill_haircut_bps:u32)->Self{Self{quotes,fill_haircut_bps}}}
#[async_trait] impl<E:Executor> Executor for PaperExecutor<E>{async fn quote(&self,a:&str,b:&str,c:u64,d:u16)->Result<Quote,ExecutionError>{self.quotes.quote(a,b,c,d).await} async fn execute(&self,r:ExecutionRequest)->Result<Fill,ExecutionError>{if r.quote.output_amount<r.min_output_amount{return Err(ExecutionError::InvalidQuote)};let output=r.quote.output_amount.saturating_mul((10_000-self.fill_haircut_bps)as u64)/10_000;if output<r.min_output_amount{return Err(ExecutionError::InvalidQuote)};Ok(Fill{order_id:r.order_id,signature:format!("paper:{}",uuid::Uuid::new_v4()),input_amount:r.quote.input_amount,output_amount:output,price_usd:Decimal::ZERO,fees_usd:Decimal::ZERO,slippage_bps:r.quote.price_impact_bps+self.fill_haircut_bps,confirmed_at:Utc::now(),latency_ms:0})} async fn health(&self)->Result<(),ExecutionError>{self.quotes.health().await}}
